// This style of import is necessary for storybook to automatically generate the documentation for prop types and control interface
import * as React from "react";
import "./Loader.scss";

// Extend existing React interface that covers all HTML button attributes
export interface LoaderProps {
  /**
   * Identifying value for the loader.
   */
  id: string;
  /**
   * Determines the size of the loader.
   */
  size?: "extra large" | "large" | "medium" | "small";
}

const CircularLoader: React.FC<LoaderProps> = ({
  id,
  size = "extra large",
}) => {
  
  let size_px = "100px";
  switch (size) {
    case "extra large":
      size_px = "100px";
      break;
    case "large":
      size_px = "60px";
      break;
    case "medium":
      size_px = "40px";
      break;
    case "small":
      size_px = "25px"
      break;
    default:
      size_px = "100px";
      break;
  }
  
  return (
    <div id={id}>
      <div className="flex items-center justify-center min-h-screen">
        <div className="loader" style={{width: size_px,height: size_px}}></div>
      </div>
    </div>
  );
};

export default CircularLoader;
